def test_at_least_100_fps_cases():
    assert len(CASES) >= 100


@pytest.mark.parametrize("case", CASES, ids=[case["id"] for case in CASES])
def test_steam_fps_case(case):
    estimate = resolve_fps(
        case["gpu"],
        case["cpu"],
        case["payload"],
        api_available=case["api_available"],
        local_cluster_id=case["local_cluster_id"],
        cluster_map=case["cluster_map"],
    )
    assert estimate.expected_fps == case["expected_fps"]
    assert estimate.fps_min == case["fps_min"]
    assert estimate.fps_max == case["fps_max"]
    assert estimate.fps_source == case["fps_source"]
